INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active)
VALUES ('6OHL9UTCTlM','German electronic music and its star DJs – Felix Jaehn, Paul van Dyk, Alle Farben | DW Documentary','A hit song or remix from German DJs and producers Felix Jaehn, Alle Farben and Paul van Dyk can excite and animate music fans all around the world. The potential to conquer international charts with beats created on a laptop is huge and growing. DJs like Felix Jaehn, Alle Farben and trance pioneer Paul van Dyk are taking their EDM tracks to international audiences through extensive tours and social media campaigns. But what happens to people in their early twenties who have already reached what others need an entire career to achieve? What drives this young generation of laptop producers? And what does a DJ say, who is a veteran of the business? The documentary “Superstar DJs - Made in Germany” accompanies Alle Farben, Felix Jaehn and Paul van Dyk on one of their worldwide gigs. Join us as Jaehn performs on the main stage at the biggest festival in the Baltic region. We also witness Frans Zimmer aka Alle Farben battling against torrential rain and technical mishaps on the Dutch border. And at a rave in San Francisco we talk to Paul van Dyk about what still motivates him after a near-fatal accident during a concert. The report portrays a working world defined by backstage areas, self-discipline and permanent social media activity. From Felix Jaehn and Alle Farben to Paul van Dyk: all three are in big demand, but each has their own individual perspective on music, success and a scene where - contrary to what some may imagine - nobody becomes a star just like that. “Superstar DJs - Made in Germany” reveals a privileged but tough business. It involves fame, fortune and fun, as well as, little sleep, preset schedules and a festival summer with no fixed abode. __ DW Documentary gives you knowledge beyond the headlines. Watch top documentaries from German broadcasters and international production companies. Meet intriguing people, travel to distant lands, get a look behind the complexities of daily life and build a deeper understanding of current affairs and global events. Subscribe and explore the world around you with DW Documentary. Subscribe to: DW Documentary: https://www.youtube.com/channel/UCW39zufHfsuGgpLviKh297Q?sub_confirmation=1# DW Documental (Spanish): https://www.youtube.com/dwdocumental DW Documentary (Arabic): https://www.youtube.com/dwdocarabia For more visit: http://www.dw.com/en/tv/docfilm/s-3610 Instagram: https://www.instagram.com/dwdocumentary/ Facebook: https://www.facebook.com/dw.stories We kindly ask viewers to read and stick to the DW netiquette policy on our channel: https://p.dw.com/p/MF1G','https://i.ytimg.com/vi/6OHL9UTCTlM/maxresdefault.jpg','Documentaries','DW Documentary','DW Documentary','UCW39zufHfsuGgpLviKh297Q','DOCUMENTARY','2017-11-24T10:57:03Z','','','{"id":"6OHL9UTCTlM","title":"German electronic music and its star DJs – Felix Jaehn, Paul van Dyk, Alle Farben | DW Documentary","description":"A hit song or remix from German DJs and producers Felix Jaehn, Alle Farben and Paul van Dyk can excite and animate music fans all around the world. The potential to conquer international charts with beats created on a laptop is huge and growing. DJs like Felix Jaehn, Alle Farben and trance pioneer Paul van Dyk are taking their EDM tracks to international audiences through extensive tours and social media campaigns. But what happens to people in their early twenties who have already reached what others need an entire career to achieve? What drives this young generation of laptop producers? And what does a DJ say, who is a veteran of the business? The documentary “Superstar DJs - Made in Germany” accompanies Alle Farben, Felix Jaehn and Paul van Dyk on one of their worldwide gigs. Join us as Jaehn performs on the main stage at the biggest festival in the Baltic region. We also witness Frans Zimmer aka Alle Farben battling against torrential rain and technical mishaps on the Dutch border. And at a rave in San Francisco we talk to Paul van Dyk about what still motivates him after a near-fatal accident during a concert. The report portrays a working world defined by backstage areas, self-discipline and permanent social media activity. From Felix Jaehn and Alle Farben to Paul van Dyk: all three are in big demand, but each has their own individual perspective on music, success and a scene where - contrary to what some may imagine - nobody becomes a star just like that. “Superstar DJs - Made in Germany” reveals a privileged but tough business. It involves fame, fortune and fun, as well as, little sleep, preset schedules and a festival summer with no fixed abode. __ DW Documentary gives you knowledge beyond the headlines. Watch top documentaries from German broadcasters and international production companies. Meet intriguing people, travel to distant lands, get a look behind the complexities of daily life and build a deeper understanding of current affairs and global events. Subscribe and explore the world around you with DW Documentary. Subscribe to: DW Documentary: https://www.youtube.com/channel/UCW39zufHfsuGgpLviKh297Q?sub_confirmation=1# DW Documental (Spanish): https://www.youtube.com/dwdocumental DW Documentary (Arabic): https://www.youtube.com/dwdocarabia For more visit: http://www.dw.com/en/tv/docfilm/s-3610 Instagram: https://www.instagram.com/dwdocumentary/ Facebook: https://www.facebook.com/dw.stories We kindly ask viewers to read and stick to the DW netiquette policy on our channel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/6OHL9UTCTlM/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2017-11-24T10:57:03Z","viewCount":55007,"durationSeconds":2546,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
