INSERT OR IGNORE INTO videos (id,title,description,thumbnail,category,channel,channel_title,channel_id,badge,published_at,city,country,raw_json,active)
VALUES ('xwcWA_SymA4','A sperm donor and his 30 children | DW Documentary','Gerrit has 30 children. And they all know about each other. Gerrit is a private sperm donor. He helps lesbian couples to start a family. The only condition: full transparency. "Every child needs to know where it comes from,” says Gerrit. And so Gerrit and the mothers whose children are the result of his donation have founded an extraordinary network. They jokingly call themselves "the herd”. The highlight of each year is the so-called herd meeting. Gerrit invites all the mothers and children to his home in Hamburg. Gerrit''s wife and his own three sons are also there. Gerrit’s children like it: they spend a weekend romping around the garden with all their half-siblings. #documentary #dwdocumentary #dwdocs #biology #spermdonor ______ DW Documentary gives you knowledge beyond the headlines. Watch top documentaries from German broadcasters and international production companies. Meet intriguing people, travel to distant lands, get a look behind the complexities of daily life and build a deeper understanding of current affairs and global events. Subscribe and explore the world around you with DW Documentary. Subscribe to: ‬ ⮞ DW Documentary (English): https://www.youtube.com/dwdocumentary ⮞ DW Documental (Spanish): https://www.youtube.com/dwdocumental ⮞ DW Documentary وثائقية دي دبليو (Arabic): https://www.youtube.com/dwdocarabia ⮞ DW Documentary हिन्दी (Hindi): https://www.youtube.com/dwdochindi ⮞ DW Doku (German): https://www.youtube.com/dwdoku For more visit: http://www.dw.com/en/tv/docfilm/s-3610 Follow DW Documentary on Instagram: https://www.instagram.com/dwdocumentary/ Follow DW Documental on Facebook: https://www.facebook.com/dwdocumental We kindly ask viewers to read and stick to the DW netiquette policy on our channel: https://p.dw.com/p/MF1G','https://i.ytimg.com/vi/xwcWA_SymA4/maxresdefault.jpg','Documentaries','DW Documentary','DW Documentary','UCW39zufHfsuGgpLviKh297Q','DOCUMENTARY